                'book' => $book,
                'chapter' => $chapter,
                'verse' => $verse,
                'reference' => sprintf('%s %d:%d', $book, $chapter, $verse),
                'text' => $text,
                'created_at' => now(),
                'updated_at' => now(),
            ];
        }

